/**
 * @param {number[]} nums
 * @return {number[]}
 */
var separateDigits = function(nums) {
    const res = [];

    for (let i = nums.length - 1; i >= 0; i--) {
        let num = nums[i];

        while (num > 0) {
            res.push(num % 10);
            num = Math.floor(num / 10);
        }
    }

    return res.reverse();
};
